void syscall_enter_handler(void* ignore, struct pt_regs* regs, long id) {
    int syscall_number = pt_regs_get_arg1(regs);  // Assuming a helper to get the syscall number
    if (!is_valid_syscall(syscall_number) || !is_syscall_enabled(syscall_number)) {
        return;
    }

    struct syscall_metadata* metadata = get_syscall_metadata(syscall_number);
    if (!metadata || !(metadata->flags & SYS_CALL_RECORD_ENTER)) {
        return;
    }

    size_t size = metadata->size;
    size_t aligned_size = ALIGN(size, 8);  // Assuming a helper for alignment

    struct trace_record* record = prepare_trace_record(aligned_size);
    if (!record) {
        return;
    }

    fill_trace_record_with_args(record, regs, id, metadata);
    submit_trace_record(record);
}

void syscall_enter(void *ignore, struct pt_regs *regs, long id) {
    int syscall_nr = pt_regs_SYSCALL(regs);
    struct syscall_metadata *metadata = find_syscall_metadata(syscall_nr);
    if (!metadata || !(metadata->flags & SYS_ENTER_EVENT))
        return;

    size_t size = metadata->enter_size;
    if (!size)
        return;

    struct trace_event_file *file = find_event_file(SYSCALL_EVENT, metadata->enter_event);
    if (!file)
        return;

    size = ALIGN(size, sizeof(u64));
    struct trace_record *record = trace_buffer_lock_reserve(file->buffer, size);
    if (!record)
        return;

    fill_syscall_enter_record(record, regs, metadata);
    trace_buffer_submit(record, file, 1, 0);
}

void syscall_trace_entry(void *ignore, struct pt_regs *regs, long id) {
    int syscall_nr = pt_regs_SYSCALL(regs);
    struct syscall_metadata *meta = get_syscall_metadata(syscall_nr);

    if (!meta || !syscall_enabled(syscall_nr))
        return;

    if (!trace_event_enabled(meta->event))
        return;

    int size = sizeof(struct syscall_trace) + sizeof(u64) * meta->num_args;
    size = ALIGN(size, 8);

    struct syscall_trace *entry = trace_buffer_reserve(size);
    if (!entry)
        return;

    entry->nr = syscall_nr;
    for (int i = 0; i < meta->num_args; ++i) {
        entry->args[i] = get_syscall_arg(meta->arg_info[i], regs);
    }

    trace_buffer_commit(entry);
}

void syscall_enter(void *ignore, struct pt_regs *regs, long id)
{
    int syscall_nr = regs->syscallno;
    struct syscall_metadata *meta = get_syscall_metadata(syscall_nr);

    if (!meta || !meta->enabled)
        return;

    if (unlikely(!trace_events_enabled))
        return;

    size_t size = sizeof(struct syscall_trace_event);
    size = ALIGN(size, 8);

    struct syscall_trace_event *entry = ring_buffer_get_event_data(size);
    if (!entry)
        return;

    entry->syscall_nr = syscall_nr;
    entry->id = id;

    for (int i = 0; i < meta->nr_args; i++) {
        entry->args[i] = regs->args[i];
    }

    ring_buffer_submit_event(entry, size);
}
